window.ox.install(({action})=>{const visible=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>0&&r.height>0&&s.visibility!=='hidden'&&s.display!=='none'};async function ready(){const until=Date.now()+15000;while(Date.now()<until){if(visible(document.getElementById('email-address'))&&visible(document.getElementById('password'))&&visible(document.getElementById('sign-in-btn')))return true;await new Promise(r=>setTimeout(r,200));}return false;}const cleanText = value => String(value ?? "").replace(/\s+/g, " ").trim();

const usable = element => {
  if (!element || element.disabled || element.readOnly || element.type === "hidden") return false;
  if (element.closest("[hidden], [aria-hidden='true'], [inert]")) return false;
  const style = getComputedStyle(element);
  return style.display !== "none" && style.visibility !== "hidden";
};

const waitForStep = async (detectors, timeout = 15000) => {
  const end = Date.now() + timeout;
  while (Date.now() < end) {
    for (const [kind, detect] of Object.entries(detectors)) {
      const match = detect();
      if (match) return { kind, match };
    }
    await new Promise(resolve => setTimeout(resolve, 200));
  }
  return { kind: "unknown", match: null };
};

const typeInto = (field, value) => {
  field.focus();
  field.select?.();
  if (!document.execCommand("insertText", false, value) || field.value !== value) {
    Object.getOwnPropertyDescriptor(Object.getPrototypeOf(field), "value").set.call(field, value);
    field.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText", data: value }));
  }
  field.dispatchEvent(new Event("change", { bubbles: true }));
};

const pageError = (root = document) => [...root.querySelectorAll("[role='alert'], [aria-live='assertive'], [aria-live='polite']")]
  .filter(usable)
  .map(element => cleanText(element.innerText))
  .filter(Boolean)
  .join(" | ")
  .slice(0, 200);
const uscisLoginStep=async()=>waitForStep({challenge:()=>[...document.querySelectorAll('input[autocomplete="one-time-code"],iframe[src*="captcha"]')].find(usable),credentials:()=>{if(location.hostname!=='myaccount.uscis.gov'||location.pathname!=='/sign-in')return null;const username=document.getElementById('email-address'),password=document.getElementById('password'),submit=document.getElementById('sign-in-btn');let root=username?.parentElement;for(let n=0;n<6&&root&&!root.contains(submit);n++)root=root.parentElement;return usable(username)&&usable(password)&&usable(submit)&&root&&root!==document.body&&root.contains(password)&&root.contains(submit)?{username,password,submit,root}:null;}});
action('login',{async invoke(input,context){
const step=await uscisLoginStep();
if(step.kind==='unknown'&&!input?.account)throw Error('USCIS sign-in controls are not ready or this screen needs manual review.');
if(step.kind!=='credentials')return null;
if(!input?.account||input.account.serviceID!=='web:uscis.gov')return null;
if(pageError(step.match.root))throw Error('USCIS sign-in reports an error; automatic login stopped without retrying.');
const account=await context.secret(input.account);
typeInto(step.match.username,account.username);
typeInto(step.match.password,account.password);
if(!usable(step.match.submit))throw Error('USCIS Sign In button unavailable.');
step.match.submit.click();
return null;
}});
async function identity(){const r=await fetch('https://my.uscis.gov/account/applicant/settings',{credentials:'include'});if(!r.ok)throw Error('Settings HTTP '+r.status);if(new URL(r.url).hostname==='myaccount.uscis.gov')return null;const d=new DOMParser().parseFromString(await r.text(),'text/html');const el=d.querySelector('script[data-component-name="SettingsApp"]');if(!el)throw Error('Account identity unavailable');const email=JSON.parse(el.textContent).applicant?.email;if(!email)throw Error('Account email missing');return email;} action('listSessions',{async invoke(){if(location.hostname==='www.uscis.gov')return [];if(location.hostname==='egov.uscis.gov'){if(document.querySelector('#receipt_number'))return [];throw Error('Public lookup not ready');}if(location.hostname==='myaccount.uscis.gov'&&await ready())return [];const email=await identity();return email?[{id:email,label:email,url:'https://my.uscis.gov/account/applicant/settings'}]:[];}});action('getCaseStatus',{async invoke(args){const input=document.querySelector('#receipt_number');const btn=[...document.querySelectorAll('button')].find(e=>e.textContent.trim()==='Check Status');if(!input||!btn)throw Error('Case lookup unavailable or security verification required');const box=document.querySelector('.caseStatus-container');if(!box)throw Error('Status container missing');const before=box.innerText;Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,args.receiptNumber);input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));await new Promise(r=>setTimeout(r,100));btn.click();const end=Date.now()+25000;while(Date.now()<end){const b=document.querySelector('.caseStatus-container');const t=b?.innerText||'';if(t!==before&&t.length>80&&!t.includes('Enter a Receipt Number'))return {receiptNumber:args.receiptNumber,text:t,url:location.href};await new Promise(r=>setTimeout(r,300));}throw Error('No verified case-status result within timeout');}});action('getLinkingOptions',{async invoke(args,{session}){const email=await identity();if(!email||email!==session?.id)throw Error('Account mismatch');const pages=[];for(const path of ['/account/onboarding/track/new','/account/v1/needhelp']){const r=await fetch(path,{credentials:'include'});if(!r.ok)throw Error('Portal HTTP '+r.status);const d=new DOMParser().parseFromString(await r.text(),'text/html');d.querySelectorAll('script,style,header,footer,nav').forEach(e=>e.remove());const e=d.querySelector('.uscis-card-content')||d.querySelector('main')||d.body;pages.push({url:r.url,text:e.textContent.replace(/\s+/g,' ').trim().slice(0,18000)});}return {pages};}});action('submitLinkReceipt',{async invoke(args,{session}){const accountEmail=await identity();if(!accountEmail)throw Error('Not signed in');if(session?.id&&accountEmail!==session.id)throw Error('Account mismatch');const e=document.querySelector('#track_a_case_receipt'),f=e?.form;if(!f||new URL(f.action).pathname!=='/account/onboarding/track'||f.method.toLowerCase()!=='post')throw Error('Expected receipt form unavailable');const btn=[...f.querySelectorAll('button')].find(b=>b.textContent.trim()==='Next');if(!btn||!visible(btn)||!visible(e))throw Error('Receipt form not usable');e.value=args.receiptNumber;e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));btn.click();return {url:location.href,text:'Next clicked; navigation outcome must be checked on the live page.',fields:[]};}});action('askEmma',{async invoke(args){let root;const end=Date.now()+20000;while(Date.now()<end){root=[...document.querySelectorAll('*')].map(e=>e.shadowRoot).find(r=>r?.querySelector('#vf-chat-button'));if(root)break;await new Promise(r=>setTimeout(r,250));}if(!root)throw Error('Emma widget unavailable');if(!root.querySelector('textarea')?.getBoundingClientRect().width)root.querySelector('#vf-chat-button').click();const ready=Date.now()+15000;while(Date.now()<ready&&!root.querySelector('textarea'))await new Promise(r=>setTimeout(r,200));const ok=[...root.querySelectorAll('button')].find(e=>e.textContent.trim()==='Ok');if(ok&&ok.getBoundingClientRect().width)ok.click();const input=root.querySelector('textarea[aria-label="Type a message"]'),btn=root.querySelector('#vf-send-button');if(!input||!btn)throw Error('Emma input not ready');Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(input,args.message);input.dispatchEvent(new Event('input',{bubbles:true,composed:true}));input.dispatchEvent(new Event('change',{bubbles:true,composed:true}));await new Promise(r=>setTimeout(r,200));if(btn.disabled)throw Error('Send disabled; nothing sent');btn.click();await new Promise(r=>setTimeout(r,2500));return {text:root.textContent.slice(-14000)};}});action('connectEmmaAgent',{async invoke(){const end=Date.now()+15000;let root;while(Date.now()<end){root=[...document.querySelectorAll('*')].map(e=>e.shadowRoot).find(r=>r?.querySelector('#vf-chat-button'));if(root)break;await new Promise(r=>setTimeout(r,250));}if(!root)throw Error('Emma widget unavailable');if(!root.querySelector('textarea')?.getBoundingClientRect().width)root.querySelector('#vf-chat-button').click();const until=Date.now()+15000;let button;while(Date.now()<until){const ok=[...root.querySelectorAll('button')].find(e=>e.textContent.trim()==='Ok');if(ok&&ok.getBoundingClientRect().width)ok.click();button=[...root.querySelectorAll('button')].find(e=>e.textContent.trim()==='Connect To Live Agent');if(button&&!button.disabled&&button.getBoundingClientRect().width)break;await new Promise(r=>setTimeout(r,250));}if(!button||button.disabled)throw Error('Live agent option not available; no request sent');button.click();await new Promise(r=>setTimeout(r,2000));return {text:root.textContent.slice(-16000)};}});action('readEmma',{async invoke(){const root=[...document.querySelectorAll('*')].map(e=>e.shadowRoot).find(r=>r?.querySelector('#vf-chat-button'));if(!root)throw Error('Chat missing');return {text:root.textContent.slice(-14000)};}});action('getLinkedCasesSummary',{async invoke(args,{session}){const email=await identity();if(!email||(session?.id&&session.id!==email))throw Error('Account mismatch');const end=Date.now()+15000;while(Date.now()<end){const headings=[...document.querySelectorAll('h1,h2,h3,h4')].map(e=>e.textContent.trim());if(headings.some(t=>t==='Your cases'))return {headings:headings.filter(t=>/^I-|Case |Your cases/.test(t)),receipts:[...new Set(document.body.innerText.match(/\b[A-Z]{3}[0-9]{10}\b/g)||[])],url:location.href};await new Promise(r=>setTimeout(r,250));}throw Error('Linked case dashboard not ready');}});action('getCaseNotices',{async invoke(args,{session}){const email=await identity();if(!email||(session?.id&&email!==session.id))throw Error('Account mismatch');const end=Date.now()+15000;while(!document.querySelector('.react-tabs')&&Date.now()<end)await new Promise(r=>setTimeout(r,200));const groups=[...document.querySelectorAll('.react-tabs')].map(el=>({el,receipt:el.parentElement.innerText.match(/\b[A-Z]{3}[0-9]{10}\b/)?.[0]}));if(!groups.length||groups.some(g=>!g.receipt))throw Error('Case card identity not ready');const cases=[];for(const g of groups){const item={receipt:g.receipt,notices:'',history:''};for(const label of ['Documents','Case History']){const tab=[...g.el.querySelectorAll('[role=tab]')].find(e=>e.textContent.trim()===label);if(!tab)throw Error('Missing tab');tab.click();const deadline=Date.now()+7000;let panel;while(Date.now()<deadline){panel=document.getElementById(tab.getAttribute('aria-controls'));if(panel?.innerText.trim()&&!/loading/i.test(panel.innerText)&&panel.querySelector('table'))break;await new Promise(r=>setTimeout(r,200));}if(!panel?.innerText.trim())throw Error('Panel incomplete');if(label==='Documents'){const h=[...panel.querySelectorAll('h3')].find(e=>e.textContent.trim()==='USCIS Notices');if(!h)throw Error('Notice section missing');item.notices=h.parentElement.innerText;}else item.history=panel.innerText;}cases.push(item);}return {cases};}});action('downloadCaseNotices',{async invoke(args,{session}){const email=await identity();if(!email||(session?.id&&session.id!==email))throw Error('Account mismatch');const end=Date.now()+15000;let group;while(Date.now()<end){group=[...document.querySelectorAll('.react-tabs')].find(e=>e.parentElement.innerText.includes(args.receiptNumber));if(group)break;await new Promise(r=>setTimeout(r,200));}if(!group)throw Error('Case not found');const tab=[...group.querySelectorAll('[role=tab]')].find(e=>e.textContent==='Documents');tab.click();const until=Date.now()+10000;let section;while(Date.now()<until){const panel=document.getElementById(tab.getAttribute('aria-controls'));const h=[...panel.querySelectorAll('h3')].find(e=>e.textContent==='USCIS Notices');if(h&&h.parentElement.querySelector('table')){section=h.parentElement;break;}await new Promise(r=>setTimeout(r,200));}if(!section)throw Error('Notices not ready');const files=[];for(const a of [...section.querySelectorAll('a.document-download')].slice(0,10)){const r=await fetch(a.href,{credentials:'include'});if(!r.ok)throw Error('Document HTTP '+r.status);const bytes=new Uint8Array(await r.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=16384)raw+=String.fromCharCode(...bytes.subarray(i,i+16384));files.push({name:a.textContent,base64:btoa(raw)});}return {files};}});});